// The summary line after anomaly detection.
export function detectionSummary(scores, threshold) {
  const finite = scores.filter(Number.isFinite);
  if (finite.length === 0) throw new Error('No pixel has a finite score, so there is nothing to report');
  const hits = finite.filter((s) => s >= threshold).length;
  const best = finite.sort((a, b) => b - a)[0];
  return hits + ' pixels above ' + threshold + '; best score ' + best.toPrecision(3);
}

