import { test } from 'node:test';
import assert from 'node:assert/strict';
import { detectionSummary } from '../src/detect-summary.js';

test('the summary counts hits and gives the best score', () => {
  assert.equal(detectionSummary([0.2, NaN, 0.9, 0.5], 0.4), '2 pixels above 0.4; best score 0.900');
});

test('no finite score is refused by name', () => {
  assert.throws(() => detectionSummary([NaN, Infinity], 0.4), /no pixel has a finite score/i);
});
